//! Procedural plumbing acceptance scene; all geometry and baked maps are generated by Rust.
use std::collections::BTreeMap;
use superspec_aml::material::Material;
use superspec_engine::{
    Scene, compile,
    materialspec::surface::Inputs,
    worldspec::themes::kowloon::{
        fixture::Fixture,
        mesh::{Mesh, Mode},
        metal::Binding,
        pen::Pen,
        pipes::{Options, PipeSystem},
        weathered::{self, Settings},
    },
};
use superspec_geometry::Matrix;

pub fn options() -> Options {
    Options {
        radius: 0.07,
        color: [0.2, 0.5, 0.8],
        sides: 16,
        variant: "pipe-standard".into(),
        weathering: Some(Settings {
            seed: "pipe-scene".into(),
            wear: 0.6,
            grime: 0.7,
            rust: 0.4,
            texture_density: 128.,
            metal: Binding {
                material: "metal".into(),
                repeat: 1.,
            },
            sheet: Binding {
                material: "metal".into(),
                repeat: 1.,
            },
            paint: Binding {
                material: "paint".into(),
                repeat: 1.,
            },
        }),
    }
}
pub fn materials() -> BTreeMap<String, Material> {
    BTreeMap::from([
        (
            "metal".into(),
            Material {
                id: "metal".into(),
                color: "#a4a9aa".into(),
                roughness: 0.55,
                metalness: 0.9,
                ..Material::default()
            },
        ),
        (
            "paint".into(),
            Material {
                id: "paint".into(),
                color: "#ffffff".into(),
                roughness: 0.85,
                ..Material::default()
            },
        ),
    ])
}
pub fn scene() -> Scene {
    let mut scene=compile(r#"<architecture version="1" id="rust-pipes"><box id="host" width="2" depth=".1" height="3.3" visible="false"/></architecture>"#,0).unwrap();
    let mut mesh = Mesh::new(Mode::Render, 20000, &|| false).unwrap();
    let pen = Pen::new(
        Matrix([[1., 0., 0.], [0., -1., 0.], [0., 0., 1.], [0.; 3]]),
        "pipes",
    )
    .unwrap();
    PipeSystem::new(options())
        .unwrap()
        .run(
            &mut Fixture {
                pen,
                mesh: &mut mesh,
                repeats: &|_| 1.,
            },
            &[
                [0.2, 0.3, 0.1],
                [0.2, 0.3, 3.2],
                [1.8, 0.3, 3.2],
                [1.8, 0.3, 1.8],
            ],
            Some(0.),
        )
        .unwrap();
    let materials = materials();
    let bakes = weathered::finish(&mut mesh, &|| false)
        .unwrap()
        .bake(
            &Inputs {
                materials: &materials,
                images: &BTreeMap::new(),
            },
            "pipes",
            &|| false,
        )
        .unwrap();
    let mut bindings: BTreeMap<String, String> = bakes
        .iter()
        .map(|b| (b.material().id.clone(), b.material().id.clone()))
        .collect();
    for id in ["metal", "paint"] {
        bindings.insert(id.into(), id.into());
        scene.manifest.materials.push(materials[id].clone());
    }
    scene
        .append_baked_visual("host", &mesh, &bindings, &bakes)
        .unwrap();
    scene
}
